-- RD-95: "?" em todo campo/ação/indicador da tela de Produtos (/dashboard/cadastros/produtos).
-- A aba Fiscal do ProdutoForm não tinha nenhuma ajuda; faltavam também campos do Básico e Preços,
-- as 6 ações do header e os 2 banners. Aditivo: só INSERT de texto (ON CONFLICT DO NOTHING),
-- nunca altera dado de cliente. Agente code-desenvolvedor-3 (faixa de segundos :35–:44).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, v.grupo, v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem,
       '/dashboard/cadastros/produtos', 'gestao_empresarial', 'publicado'
FROM (VALUES
 -- Aba Básico (campos do formulário)
 ('cadastros.produtos.codigo', 'Produto · Básico', 'Código (interno)', 'Um código curto e único que identifica o produto na sua empresa. Você escolhe o padrão (letras e números).', 'Localiza o produto em vendas, compras e estoque, e é o que a etiqueta usa quando não há código de barras.', 'TINTA-18L ou PROD-001.', 'Repetir um código que já existe: o sistema avisa e não deixa salvar. Use outro.', 1),
 ('cadastros.produtos.nome', 'Produto · Básico', 'Nome', 'O nome comercial do produto, como aparece na nota e nas listas.', 'É o texto principal que todos veem ao procurar e vender o item.', 'Tinta acrílica branca 18L.', 'Nome genérico demais ("tinta") que se confunde com outros itens.', 2),
 ('cadastros.produtos.descricao', 'Produto · Básico', 'Descrição', 'Detalhes extras do produto (cor, medida, marca). Entra na descrição da NFe.', 'Deixa a nota e o catálogo mais completos sem poluir o nome.', 'Acabamento fosco, rendimento 10 m²/L, base água.', 'Escrever um segundo nome aqui em vez de complementar o nome.', 3),
 ('cadastros.produtos.unidade', 'Produto · Básico', 'Unidade', 'A unidade de medida em que você vende este item.', 'Define como a quantidade é contada em vendas, estoque e nota.', 'UN, KG, M, L ou CX.', 'Misturar unidade de compra (CX) com a de venda (UN) — use a unidade de venda aqui.', 4),
 ('cadastros.produtos.localizacao', 'Produto · Básico', 'Local de armazenagem', 'Onde o produto fica guardado no seu depósito ou loja.', 'Ajuda a separar e conferir o item mais rápido na hora de expedir.', 'Galpão B · Prateleira 3.', 'Deixar vago ("estoque") quando há vários locais — dificulta achar o item.', 5),
 ('cadastros.produtos.codigo_barras', 'Produto · Básico', 'Código de barras (EAN)', 'O número do código de barras do produto (GTIN/EAN). Deixe vazio se não tiver.', 'Permite ler o produto no leitor e imprimir etiqueta com o código real.', '7891234567890.', 'Digitar um EAN inválido: a etiqueta sai errada. Vazio = a etiqueta usa o código interno.', 6),
 -- Aba Fiscal
 ('cadastros.produtos.ncm', 'Produto · Fiscal', 'NCM (8 dígitos)', 'O código NCM de 8 dígitos que classifica o produto para a Receita. Confirme com seu contador.', 'Define a tributação na NFe; sem NCM certo a nota pode ser rejeitada ou tributada errado.', '32091010 (tintas).', 'Usar NCM de outro produto parecido — a tributação sai errada. Confira na tabela oficial.', 10),
 ('cadastros.produtos.cest', 'Produto · Fiscal', 'CEST', 'O código CEST, obrigatório só quando o produto está em substituição tributária (ST).', 'Identifica o item nas regras de ST; a NFe exige quando o NCM tem ST.', '2100100 (bebidas).', 'Preencher CEST em item que não tem ST, ou deixar vazio quando o NCM exige.', 11),
 ('cadastros.produtos.cfop_dentro', 'Produto · Fiscal', 'CFOP venda dentro do estado', 'O CFOP usado quando você vende para cliente do mesmo estado.', 'A NFe usa este CFOP nas vendas internas; define natureza da operação e impostos.', '5102 (venda) ou 5405 (com ST).', 'Trocar o CFOP de dentro pelo de fora do estado.', 12),
 ('cadastros.produtos.cfop_fora', 'Produto · Fiscal', 'CFOP venda fora do estado', 'O CFOP usado quando você vende para cliente de outro estado.', 'A NFe usa este CFOP nas vendas interestaduais.', '6102 (venda) ou 6404 (com ST).', 'Usar o mesmo CFOP de dentro do estado nas vendas para fora.', 13),
 ('cadastros.produtos.origem', 'Produto · Fiscal', 'Origem', 'De onde vem a mercadoria: nacional, importada direta, do mercado interno etc.', 'Compõe o CST do ICMS na NFe; a Receita usa para controle de importação.', '0 · Nacional.', 'Marcar nacional para item importado (ou o contrário).', 14),
 ('cadastros.produtos.cst_icms', 'Produto · Fiscal', 'CST / CSOSN ICMS', 'A situação tributária do ICMS. No Simples use CSOSN (102, 500…); no regime normal use CST (00, 60…).', 'Diz à NFe como o ICMS é cobrado neste item.', 'Simples: 102. Normal: 00. Com ST: 500/60.', 'Usar CST de regime normal estando no Simples (ou vice-versa).', 15),
 ('cadastros.produtos.aliquota_icms', 'Produto · Fiscal', 'Alíquota ICMS (%)', 'O percentual de ICMS do produto, quando houver. Deixe vazio se não se aplica.', 'Calcula o ICMS na NFe quando a situação tributária cobra o imposto.', '18 (para 18%).', 'Informar alíquota em item isento/ST, ou deixar vazio quando deveria ter.', 16),
 ('cadastros.produtos.aliquota_ipi', 'Produto · Fiscal', 'Alíquota IPI (%)', 'O percentual de IPI do produto (geralmente só indústria/importador). 0 se não tem.', 'Calcula o IPI na NFe quando o item é tributado.', '5 (para 5%).', 'Preencher IPI em revenda de item que já veio com IPI do fornecedor.', 17),
 ('cadastros.produtos.cst_pis', 'Produto · Fiscal', 'CST PIS', 'O código da situação do PIS para este produto.', 'Define como o PIS entra na NFe.', '01 (tributável) ou 49 (outras).', 'Usar CST de regime diferente do seu enquadramento.', 18),
 ('cadastros.produtos.aliquota_pis', 'Produto · Fiscal', 'Alíquota PIS (%)', 'O percentual de PIS, quando o CST exige. Deixe vazio se não se aplica.', 'Calcula o PIS na NFe.', '1.65 (para 1,65%).', 'Informar alíquota com CST de não tributado.', 19),
 ('cadastros.produtos.cst_cofins', 'Produto · Fiscal', 'CST COFINS', 'O código da situação da COFINS para este produto.', 'Define como a COFINS entra na NFe.', '01 (tributável) ou 49 (outras).', 'Usar CST que não combina com o CST do PIS.', 20),
 ('cadastros.produtos.aliquota_cofins', 'Produto · Fiscal', 'Alíquota COFINS (%)', 'O percentual de COFINS, quando o CST exige. Deixe vazio se não se aplica.', 'Calcula a COFINS na NFe.', '7.6 (para 7,6%).', 'Informar alíquota com CST de não tributado.', 21),
 ('cadastros.produtos.vbcst_ret', 'Produto · Fiscal', 'vBCSTRet · Base ICMS ST retido (R$/un)', 'A base de cálculo do ICMS ST já retido, por unidade. Vem da nota de compra do fornecedor.', 'Obrigatório na NFe de revenda de item com ST (CST 60/500); sem isto a SEFAZ rejeita.', '12.50 (por unidade).', 'Informar o valor total em vez do valor por unidade.', 22),
 ('cadastros.produtos.pst', 'Produto · Fiscal', 'pST · Alíquota consumidor final (%)', 'A alíquota do ICMS no destino (consumidor final). É percentual e não multiplica pela quantidade.', 'Compõe o grupo de ST retido exigido pelo leiaute da NFe.', '18 (para 18%).', 'Tratar a pST como valor em reais por unidade.', 23),
 ('cadastros.produtos.vicms_substituto', 'Produto · Fiscal', 'vICMSSubstituto · ICMS do substituto (R$/un)', 'O valor do ICMS próprio do substituto, por unidade. Vem da nota de compra.', 'Parte do grupo de ST retido obrigatório na NFe de revenda com ST.', '3.20 (por unidade).', 'Deixar vazio quando o CST é 60/500 — a nota é rejeitada.', 24),
 ('cadastros.produtos.vicms_st_ret', 'Produto · Fiscal', 'vICMSSTRet · ICMS ST retido (R$/un)', 'O valor do ICMS ST já retido pelo fornecedor, por unidade. Vem da nota de compra.', 'Fecha o grupo de ST retido exigido pelo leiaute (NT 2018.005).', '4.80 (por unidade).', 'Somar os quatro campos de ST num só — cada um tem seu lugar na nota.', 25),
 ('cadastros.produtos.anp_codigo', 'Produto · Fiscal', 'cProdANP · Código ANP (SIMP)', 'O código do combustível/lubrificante na tabela SIMP da ANP. Fixo por produto.', 'Obrigatório na NFe de combustível (NCM 2710); sem ele a SEFAZ rejeita o grupo.', '320101001.', 'Inventar o código: use o oficial da tabela ANP.', 26),
 ('cadastros.produtos.anp_descricao', 'Produto · Fiscal', 'descANP · Descrição ANP', 'A descrição do produto conforme a ANP, que acompanha o código SIMP.', 'Vai junto do código ANP no grupo de combustível da NFe.', 'Gasolina C comum.', 'Usar o nome comercial em vez da descrição oficial da ANP.', 27),
 -- Aba Preços
 ('cadastros.produtos.preco_venda', 'Produto · Preços', 'Preço de venda (R$)', 'O preço com que o produto sai para o cliente.', 'É o valor usado em vendas e orçamentos; sem ele o item trava a venda.', '149,90.', 'Esquecer de atualizar quando o custo sobe — a margem some.', 30),
 ('cadastros.produtos.preco_custo', 'Produto · Preços', 'Preço de custo (R$)', 'Quanto o produto custa para você (compra ou produção).', 'Serve de base para a margem e para formar o preço de venda.', '95,00.', 'Lançar o preço de venda aqui por engano — a margem fica errada.', 31),
 ('cadastros.produtos.margem', 'Produto · Preços', 'Margem', 'Indicador (só leitura) do quanto sobra entre o preço de custo e o de venda, em %.', 'Mostra na hora se o preço de venda cobre o custo com folga.', 'Custo 95 e venda 150 → margem 36,7%.', 'Confundir margem (sobre a venda) com markup (sobre o custo).', 32),
 -- Ações do header e banners
 ('cadastros.produtos.etiquetas', 'Produto · Ações', 'Etiquetas A4', 'Abre a impressão de etiquetas (folha A4) dos produtos que você marcou na lista.', 'Gera etiquetas de prateleira/preço de vários itens de uma vez.', 'Marcar 20 itens e imprimir a folha de etiquetas.', 'Clicar sem marcar nenhum produto: o botão fica desabilitado.', 50),
 ('cadastros.produtos.fiscal_massa', 'Produto · Ações', 'Edição fiscal em massa', 'Abre a edição dos dados fiscais (NCM, CFOP, CST…) de vários produtos ao mesmo tempo.', 'Corrige a tributação de muitos itens sem abrir um por um.', 'Ajustar o CFOP de todos os itens de um grupo de uma vez.', 'Aplicar a mesma regra a itens de tributação diferente sem conferir.', 51),
 ('cadastros.produtos.autoclassificar', 'Produto · Ações', 'Auto-classificar pela base PS', 'Sugere NCM e dados fiscais a partir da base de referência do próprio sistema.', 'Acelera o preenchimento fiscal de produtos novos ou sem classificação.', 'Classificar de uma vez os itens importados sem NCM.', 'Aceitar a sugestão sem conferir: revise antes de salvar.', 52),
 ('cadastros.produtos.importar_fiscal', 'Produto · Ações', 'Importar planilha fiscal', 'Sobe uma planilha para preencher/atualizar os dados fiscais dos produtos em lote.', 'Traz NCM, CFOP e CST de muitos itens de uma só vez.', 'Importar a planilha do contador com os NCMs revisados.', 'Planilha fora do modelo esperado: baixe o modelo antes.', 53),
 ('cadastros.produtos.importar_estoque', 'Produto · Ações', 'Importar estoque (planilha)', 'Abre a importação de produtos e saldos de estoque por planilha.', 'Cadastra ou atualiza muitos produtos e quantidades de uma vez.', 'Subir a planilha inicial de estoque ao migrar para o sistema.', 'Reimportar a mesma planilha e duplicar itens — confira os códigos.', 54),
 ('cadastros.produtos.formar_precos', 'Produto · Ações', 'Formar preços', 'Leva para a tela de Precificação, onde você define markup e preço de venda.', 'Centraliza a formação de preço a partir do custo e da margem desejada.', 'Formar o preço dos itens novos antes de liberar a venda.', 'Definir preço item a item aqui quando a Precificação faz em lote.', 55),
 ('cadastros.produtos.banner_sem_preco', 'Produto · Avisos', 'Produtos sem preço de venda', 'Aviso de quantos produtos ativos ainda não têm preço de venda — eles travam a venda.', 'Chama a atenção para precificar os itens antes que faltem na venda.', '7 produtos sem preço → clicar para formar preços.', 'Ignorar o aviso e descobrir na venda que o item não tem preço.', 56),
 ('cadastros.produtos.banner_pendencia_fiscal', 'Produto · Avisos', 'Pendência fiscal (SPED 0200)', 'Aviso de produtos sem tipo do item ou sem NCM, que o contador precisa completar antes da apuração.', 'Evita erro no SPED e na apuração de impostos por item incompleto.', '3 produtos sem NCM → completar antes do fechamento.', 'Deixar para o fim do mês: a apuração pode travar por dado faltando.', 57)
) AS v(chave, grupo, rotulo, o_que, para_que, exemplo, erro, ordem)
ON CONFLICT (chave) DO NOTHING;
